<?php require 'config/db.php';require 'includes/auth.php';require_role(['ADMIN']);$page_title='Audit Log';$rows=$pdo->query('SELECT a.*,u.full_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 300')->fetchAll();require 'includes/header.php';?><section class="panel"><h2>System Audit Log</h2><div class="tablewrap"><table><tr><th>User</th><th>Action</th><th>Details</th><th>Time</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td><td><?=e($r['action_time'])?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>
